quilt-ml-recipes-main/recipes/r1-determi:
// r1-deterministic-cell-regression — a recipe card, not a library.
//
// RULE: given the same seed, the metrics of a deterministic experiment are
// byte-identical — same numbers, same sha256 of the trajectory — on any machine,
// twice in a row, forever. No Date.now(), no Math.random(), no clock anywhere
// in the metrics path. Wall time / run ids / timestamps are the HARNESS's
// business and stay out of the metrics.
//
// LINEAGE: SuperInstance/quilt-lab @ d2a8b2b (task 67-b), the worked example
// experiments/linear-cell-regression/. Code copied verbatim so the pinned
// trajectory sha carries over. Self-contained on purpose: copy this file into
// any repo and it runs — that is what makes it a recipe and not a dependency.
//
// ZERO dependencies, ESM, Node >= 18.

import { createHash } from 'node:crypto';

export const meta = {
  id: 'r1-deterministic-cell-regression',
  title: 'Deterministic cell regression',
  lineage: 'SuperInstance/quilt-lab (67-b) — experiments/linear-cell-regression',
  proves: 'same seed ⇒ byte-identical metrics, pinned by a trajectory sha',
};

// ── the recipe constants (the pin: change any of these and the sha changes) ─────
const N = 200; // dataset size
const STEPS = 500; // gradient-descent steps
const LR = 0.5; // learning rate
const NOISE = 0.1; // uniform noise amplitude (±)
export const PIN = {
  seed: 42,
  mse_final: 0.003195525129, // measured on this checkout, twice
  mse_trajectory_sha: '1392d453ec1d13a45a4e85835f59b52af083ec7ffc3c2026b65f75bacea125b0',
  // sha256 over the CANONICAL metrics.json bytes (pretty JSON + newline), exactly
  // what quilt-lab's ledger sealed for this experiment in task 67-b — reproduced
  // here byte-for-byte, cross-repo, from copied code alone:
  metrics_file_sha: '7b7364d3ccfe558252bdc14e5c1a4978ce33a394f6b00aff20f9710e395fe1e7',
};

export const metricsFileBytes = (metrics) => JSON.stringify(metrics, null, 2) + '\n';

// mulberry32 — tiny seeded PRNG, stable across runs.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 12-decimal rounding: a deliberate guard so cross-machine FP drift can never
// turn into a byte difference in metrics.json.
const r12 = (x) => Math.round(x * 1e12) / 1e12;

// The recipe body. quilt-lab contract: export async function run(ctx) with
// ctx = {seed, workdir, log}; the return value IS the metrics.
export async function run(ctx = {}) {
  const { seed = PIN.seed, log = () => {} } = ctx;
  log(`r1-deterministic-cell-regression: seed=${seed} n=${N} steps=${STEPS} lr=${LR} noise=±${NOISE}`);

  const rand = mulberry32(seed);

  // Seeded synthetic data: y = 2x + 1 + uniform noise, x ∈ [-1, 1).
  const xs = new Array(N);
  const ys = new Array(N);
  for (let i = 0; i < N; i++) {
    xs[i] = rand() * 2 - 1;
    ys[i] = 2 * xs[i] + 1 + (rand() * 2 - 1) * NOISE;
  }
  log(`data drawn: x∈[${Math.min(...xs)}, ${Math.max(...xs)}] (deterministic given seed)`);

  // Full-batch gradient descent from w=0, b=0. trajectory[t] = MSE after t+1 updates.
  let w = 0;
  let b = 0;
  const trajectory = new Array(STEPS);
  for (let s = 0; s < STEPS; s++) {
    let gw = 0;
    let gb = 0;
    for (let i = 0; i < N; i++) {
      const e = w * xs[i] + b - ys[i];
      gw += e * xs[i];
      gb += e;
    }
    w -= (LR * gw) / N;
    b -= (LR * gb) / N;
    let se = 0;
    for (let i = 0; i < N; i++) {
      const e = w * xs[i] + b - ys[i];
      se += e * e;
    }
    trajectory[s] = r12(se / N);
  }

  const mse_final = trajectory[trajectory.length - 1];
  const mse_trajectory_sha = createHash('sha256')
    .update(JSON.stringify(trajectory))
    .digest('hex');

  log(`done: mse_final=${mse_final} mse_trajectory_sha=${mse_trajectory_sha}`);
  return { mse_final, mse_trajectory_sha, steps: STEPS };
}

// The rule's own failure mode, demonstrated live (node index.mjs --negative-control):
// an unseeded Math.random() smuggled into the data path breaks byte-identity —
// two runs of the SAME experiment disagree on the first hash comparison.
export async function negativeControlDemo() {
  const brokenRun = () => {
    const rand = Math.random; // THE BUG: unseeded entropy in the metrics path
    const xs = new Array(N);
    const ys = new Array(N);
    for (let i = 0; i < N; i++) {
      xs[i] = rand() * 2 - 1;
      ys[i] = 2 * xs[i] + 1 + (rand() * 2 - 1) * NOISE;
    }
    let w = 0, b = 0, se = 0;
    for (let s = 0; s < STEPS; s++) {
      let gw = 0, gb = 0;
      for (let i = 0; i < N; i++) { const e = w * xs[i] + b - ys[i]; gw += e * xs[i]; gb += e; }
      w -= (LR * gw) / N; b -= (LR * gb) / N;
      se = 0;
      for (let i = 0; i < N; i++) { const e = w * xs[i] + b - ys[i]; se += e * e; }
    }
    return { mse_final: r12(se / N), steps: STEPS };
  };
  const a = brokenRun(), b = brokenRun();
  return {
    broken: 'unseeded Math.random() in the data path',
    run_a_mse: a.mse_final,
    run_b_mse: b.mse_final,
    identical: JSON.stringify(a) === JSON.stringify(b),
    verdict: 'determinism broken — recipe refuses to certify such a run',
  };
}

// Assertions consumed by lib/verify.mjs (the library's receipt).
export async function assertions() {
  const a = await run({ seed: PIN.seed });
  const b = await run({ seed: PIN.seed });
  const same = JSON.stringify(a) === JSON.stringify(b);
  return [
    {
      assertion: `two runs, seed ${PIN.seed}: metrics byte-identical`,
      actual: same ? 'identical' : 'DIVERGED',
      pass: same,
    },
    {
      assertion: 'mse_final < 0.1 (failure condition)',
      actual: String(a.mse_final),
      pass: a.mse_final < 0.1,
    },
    {
      assertion: 'steps == 500 (failure condition)',
      actual: String(a.steps),
      pass: a.steps === 500,
    },
    {
      assertion: `trajectory sha == pin ${PIN.mse_trajectory_sha.slice(0, 12)}…`,
      actual: a.mse_trajectory_sha.slice(0, 12) + '…',
      pass: a.mse_trajectory_sha === PIN.mse_trajectory_sha,
    },
    {
      assertion: `metrics.json bytes hash == quilt-lab sealed pin ${PIN.metrics_file_sha.slice(0, 12)}…`,
      actual: createHash('sha256').update(metricsFileBytes(a)).digest('hex').slice(0, 12) + '…',
      pass: createHash('sha256').update(metricsFileBytes(a)).digest('hex') === PIN.metrics_file_sha,
    },
  ];
}

// Direct invocation: node recipes/r1-deterministic-cell-regression/index.mjs
if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  if (process.argv.includes('--negative-control')) {
    console.log(JSON.stringify(await negativeControlDemo(), null, 2));
  } else {
    const metrics = await run({ log: (m) => console.log('[log]', m) });
    console.log('metrics:', JSON.stringify(metrics, null, 2));
    for (const a of await assertions()) console.log(`${a.pass ? 'PASS' : 'FAIL'}  ${a.assertion}  →  ${a.actual}`);
  }
}

quilt-ml-recipes-main/recipes/r2-cellgra:
// r2-cellgraph-mlp-training — a recipe card, not a library.
//
// RULE: a neural network can be a plain JSON sheet of cells — weights, sums,
// activations, loss, analytic gradient cells and one tick cell — and training it
// is cell evaluation, deterministic end to end for a fixed seed. Pinned outcome:
// XOR, 2-4-1 tanh/sigmoid MLP, 3000 per-sample SGD epochs, lr 0.5, seed 42 ⇒
// final loss < 0.05 (measured 1.0e-4), and every epoch is a receipt in a
// sha256-linked chain that verifies.
//
// LINEAGE: SuperInstance/quilt-nn @ 1ae7977 (task 67-d) — src/cellgraph.mjs +
// src/train.mjs copied/adapted so the pinned loss and chain tip carry over.
// The graph IS data: { cells: [{id, kind, inputs, params}] }, insertion order =
// topo order, edges implied by `inputs`. No hidden state in the file format.
//
// ZERO dependencies, ESM, Node >= 18.

import { createHash } from 'node:crypto';

export const meta = {
  id: 'r2-cellgraph-mlp-training',
  title: 'Cell-graph MLP training (XOR)',
  lineage: 'SuperInstance/quilt-nn (67-d) — src/cellgraph.mjs + src/train.mjs',
  proves: 'NN-as-cell-graph trains deterministically; every epoch is a receipted chain entry',
};

// ── hashing (two representations, two jobs) ─────────────────────────────────────
// f64hex: the canonical bytes of a float — 8 bytes big-endian IEEE-754, -0
// normalized to +0 — so every last ulp is visible to the receipt.
const _dv = new DataView(new ArrayBuffer(8));

export function f64hex(x) {
  if (typeof x !== 'number' || !Number.isFinite(x)) throw new TypeError(`f64hex needs a finite number, got ${x}`);
  if (Object.is(x, -0)) x = 0;
  _dv.setFloat64(0, x, false);
  let s = '';
  for (let i = 0; i < 8; i++) s += _dv.getUint8(i).toString(16).padStart(2, '0');
  return s;
}

export function sha256hex(str) {
  return createHash('sha256').update(str, 'utf8').digest('hex');
}

export function lossShaOf(loss) {
  return sha256hex(Buffer.from(f64hex(loss), 'hex').toString('latin1'));
}

// LCG (Numerical Recipes): s = (1664525·s + 1013904223) mod 2^32. Portable
// arithmetic — no engine RNG, no crypto entropy: same seed, same bytes, forever.
export function lcg(seed) {
  let s = seed >>> 0;
  return {
    next() {
      s = (Math.imul(1664525, s) + 1013904223) >>> 0;
      return s / 4294967296;
    },
  };
}

// ── activations (value + analytic derivative in terms of the OUTPUT) ────────────
function actValue(fn, x) {
  switch (fn) {
    case 'relu': return x > 0 ? x : 0;
    case 'tanh': return Math.tanh(x);
    case 'sigmoid': return 1 / (1 + Math.exp(-x));
    default: throw new Error(`unknown act fn "${fn}"`);
  }
}
function actDeriv(fn, out) {
  switch (fn) {
    case 'relu': return out > 0 ? 1 : 0;
    case 'tanh': return 1 - out * out;
    case 'sigmoid': return out * (1 - out);
    default: throw new Error(`unknown act fn "${fn}"`);
  }
}

// ── graph validation: the array order IS a topological order ────────────────────
export function validateGraph(graph) {
  if (!graph || !Array.isArray(graph.cells)) throw new TypeError('graph must be {cells: [...]}');
  const seen = new Set();
  for (const c of graph.cells) {
    if (!c || typeof c.id !== 'string' || !c.id) throw new TypeError(`cell without id: ${JSON.stringify(c)}`);
    if (seen.has(c.id)) throw new Error(`duplicate cell id ${c.id}`);
    if (!['input', 'weight', 'sum', 'product', 'act', 'loss', 'grad', 'tick'].includes(c.kind)) {
      throw new Error(`cell ${c.id}: unknown kind "${c.kind}"`);
    }
    if (!Array.isArray(c.inputs)) throw new Error(`cell ${c.id}: inputs must be an array`);
    for (const dep of c.inputs) {
      if (!seen.has(dep)) throw new Error(`cell ${c.id} inputs ${dep}: not defined earlier (graph is not in topological order)`);
    }
    seen.add(c.id);
  }
  return graph;
}

// ── the net: a loaded graph ──────────────────────────────────────────────────────
export function loadNet(graph) {
  validateGraph(graph);
  const byId = new Map(graph.cells.map((c) => [c.id, c]));
  const isForward = (c) => ['input', 'weight', 'sum', 'product', 'act', 'loss'].includes(c.kind);
  const net = {
    graph,
    byId,
    forwardCells: graph.cells.filter(isForward),
    featureCells: graph.cells.filter((c) => c.kind === 'input' && !c.params.target),
    targetCell: graph.cells.find((c) => c.kind === 'input' && c.params.target) || null,
    weightIds: graph.cells.filter((c) => c.kind === 'weight').map((c) => c.id),
    gradCells: graph.cells.filter((c) => c.kind === 'grad'),
    tickCells: graph.cells.filter((c) => c.kind === 'tick'),
  };
  if (graph.cells.filter((c) => c.kind === 'loss').length !== 1) throw new Error('net needs exactly one loss cell');
  if (net.tickCells.length !== 1) throw new Error('net needs exactly one tick cell');
  net.lossId = graph.cells.find((c) => c.kind === 'loss').id;
  return net;
}

// ── forward evaluation ───────────────────────────────────────────────────────────
// env is a plain {cellId: number} map. Weights PERSIST in env; activations are
// recomputed per sample. sample = {x: [...], y: number}.
export function evaluateForward(net, env, sample) {
  const cells = net.byId;
  net.featureCells.forEach((c, k) => {
    const v = sample.x?.[c.params.slot ?? k];
    if (typeof v !== 'number' || !Number.isFinite(v)) throw new TypeError(`sample x[${c.params.slot ?? k}] must be a finite number`);
    env[c.id] = v;
  });
  if (net.targetCell) {
    if (typeof sample.y !== 'number' || !Number.isFinite(sample.y)) throw new TypeError('sample y must be a finite number');
    env[net.targetCell.id] = sample.y;
  }
  for (const c of net.graph.cells) {
    switch (c.kind) {
      case 'input':
      case 'weight':
      case 'grad':
      case 'tick':
        if (c.kind === 'weight' && typeof env[c.id] !== 'number') throw new Error(`weight ${c.id} not initialized — call initEnv first`);
        break;
      case 'sum': {
        let acc = 0;
        for (const dep of c.inputs) acc += env[dep]; // listed order: order-independent by construction
        env[c.id] = acc;
        break;
      }
      case 'product': {
        let acc = 1;
        for (const dep of c.inputs) acc *= env[dep];
        env[c.id] = acc;
        break;
      }
      case 'act':
        env[c.id] = actValue(c.params.fn, env[c.inputs[0]]);
        break;
      case 'loss': {
        const [pred, target] = c.inputs;
        const d = env[pred] - env[target];
        env[c.id] = d * d;
        break;
      }
      default:
        throw new Error(`forward cannot evaluate kind "${c.kind}" (${c.id})`);
    }
    if (!Number.isFinite(env[c.id])) throw new Error(`cell ${c.id} evaluated to a non-finite value (divergence or bad data)`);
  }
  return env;
}

// ── backward: analytic local gradients composed over the SAME cells ─────────────
// No separate autograd tape. Products distribute gradients via prefix/suffix
// products — exact, no division, so a zero input never poisons a sibling's gradient.
export function evaluateBackward(net, env) {
  const grad = new Map();
  const bump = (id, g) => grad.set(id, (grad.get(id) || 0) + g);
  grad.set(net.lossId, 1);
  const cells = net.forwardCells;
  for (let i = cells.length - 1; i >= 0; i--) {
    const c = cells[i];
    const g = grad.get(c.id);
    if (g === undefined) continue;
    switch (c.kind) {
      case 'loss': {
        const [pred, target] = c.inputs;
        const d = 2 * (env[pred] - env[target]);
        bump(pred, d);
        bump(target, -d);
        break;
      }
      case 'sum':
        for (const dep of c.inputs) bump(dep, g);
        break;
      case 'product': {
        const k = c.inputs.length;
        const pre = new Array(k); const suf = new Array(k);
        let p = 1; for (let j = 0; j < k; j++) { pre[j] = p; p *= env[c.inputs[j]]; }
        p = 1; for (let j = k - 1; j >= 0; j--) { suf[j] = p; p *= env[c.inputs[j]]; }
        for (let j = 0; j < k; j++) bump(c.inputs[j], g * pre[j] * suf[j]);
        break;
      }
      case 'act':
        bump(c.inputs[0], g * actDeriv(c.params.fn, env[c.id]));
        break;
      default:
        break; // input, weight: terminals
    }
  }
  return grad;
}

// ── the tick cell: one SGD step. weight -= lr * grad. Output = Σ|Δw| ────────────
export function applyTick(net, env, lr) {
  const t = net.tickCells[0];
  if (!(typeof lr === 'number' && Number.isFinite(lr) && lr > 0)) throw new TypeError(`lr must be a positive finite number, got ${lr}`);
  let total = 0;
  for (const gi of t.inputs) {
    const w = net.byId.get(gi).params.of;
    const g = env[gi];
    if (typeof g !== 'number' || !Number.isFinite(g)) throw new Error(`grad cell ${gi} has no value — run backward first`);
    const delta = lr * g;
    env[w] -= delta;
    total += Math.abs(delta);
  }
  env[t.id] = total;
  return total;
}

// ── builder: buildMLP({sizes:[2,4,1], hiddenAct:'tanh', outAct:'sigmoid'}) ──────
// Xavier-uniform weight scale sqrt(6/(fanIn+fanOut)). Output layer linear unless
// outAct is given. Then one grad cell per weight, then the tick cell over all grads.
export function buildMLP({ sizes, hiddenAct = 'tanh', outAct = null }) {
  if (!Array.isArray(sizes) || sizes.length < 2 || !sizes.every((n) => Number.isInteger(n) && n > 0)) {
    throw new TypeError('sizes must be [in, ...hidden, out] of positive integers');
  }
  const cells = [];
  for (let k = 0; k < sizes[0]; k++) cells.push({ id: `in${k}`, kind: 'input', inputs: [], params: { slot: k } });
  cells.push({ id: 'target', kind: 'input', inputs: [], params: { target: true } });

  let prevIds = [];
  for (const c of cells) if (c.kind === 'input' && !c.params.target) prevIds.push(c.id);

  const weightIds = [];
  for (let l = 0; l < sizes.length - 1; l++) {
    const fanIn = sizes[l]; const fanOut = sizes[l + 1];
    const scale = Math.sqrt(6 / (fanIn + fanOut));
    const isOut = l === sizes.length - 2;
    const act = isOut ? outAct : hiddenAct;
    const outIds = [];
    for (let j = 0; j < fanOut; j++) {
      const wIds = [];
      for (let k = 0; k < fanIn; k++) {
        const w = `w${l}_${j}_${k}`;
        cells.push({ id: w, kind: 'weight', inputs: [], params: { scale } });
        weightIds.push(w); wIds.push(w);
      }
      const b = `b${l}_${j}`;
      cells.push({ id: b, kind: 'weight', inputs: [], params: { scale } });
      weightIds.push(b);
      const pIds = [];
      for (let k = 0; k < fanIn; k++) {
        const p = `p${l}_${j}_${k}`;
        cells.push({ id: p, kind: 'product', inputs: [prevIds[k], wIds[k]], params: {} });
        pIds.push(p);
      }
      const sumId = isOut && !act ? 'pred' : `s${l}_${j}`;
      cells.push({ id: sumId, kind: 'sum', inputs: [...pIds, b], params: {} });
      if (act) {
        const aId = isOut ? 'pred' : `a${l}_${j}`;
        cells.push({ id: aId, kind: 'act', inputs: [sumId], params: { fn: act } });
        outIds.push(aId);
      } else {
        outIds.push(sumId);
      }
    }
    prevIds = outIds;
  }
  cells.push({ id: 'loss', kind: 'loss', inputs: ['pred', 'target'], params: {} });
  const gradIds = [];
  for (const w of weightIds) {
    const gid = `g_${w}`;
    cells.push({ id: gid, kind: 'grad', inputs: ['loss'], params: { of: w } });
    gradIds.push(gid);
  }
  cells.push({ id: 'tick', kind: 'tick', inputs: gradIds, params: { lr: 0.5 } });
  return { cells };
}

// ── receipt chain (quilt-neighbourhood idiom, one entry per epoch) ──────────────
export const GENESIS = '0'.repeat(64);

export function initEnv(net, seed, stream) {
  const r = stream || lcg(seed);
  const env = {};
  for (const c of net.graph.cells) env[c.id] = 0;
  for (const w of net.weightIds) env[w] = (2 * r.next() - 1) * net.byId.get(w).params.scale;
  return env;
}

export function weightRootSha(net, env) {
  let buf = '';
  for (const w of net.weightIds) buf += `${w}\n${f64hex(env[w])}\n`;
  return sha256hex(buf);
}

function canonEntry(e) {
  return JSON.stringify({ v: e.v, seq: e.seq, epoch: e.epoch, loss: e.loss, loss_sha: e.loss_sha, weight_root_sha: e.weight_root_sha, prev: e.prev });
}

export function verifyWhy(chain) {
  if (!Array.isArray(chain)) return { ok: false, at: 0, reason: 'chain is not an array' };
  if (chain.length === 0) return { ok: true, n: 0 };
  let prev = GENESIS;
  for (let i = 0; i < chain.length; i++) {
    const e = chain[i];
    if (typeof e !== 'object' || e === null) return { ok: false, at: i, reason: 'entry is not an object' };
    if (e.seq !== i + 1) return { ok: false, at: i, reason: `seq is ${e.seq}, expected ${i + 1}` };
    if (!Number.isInteger(e.epoch) || e.epoch !== i) return { ok: false, at: i, reason: `epoch is ${e.epoch}, expected ${i}` };
    if (typeof e.loss !== 'number' || !Number.isFinite(e.loss)) return { ok: false, at: i, reason: `loss ${e.loss} is not a finite number` };
    if (e.prev !== prev) return { ok: false, at: i, reason: `prev-link broken` };
    if (e.loss_sha !== lossShaOf(e.loss)) return { ok: false, at: i, reason: `loss_sha does not match canonical bytes of loss` };
    if (!/^[0-9a-f]{64}$/.test(e.loss_sha) || !/^[0-9a-f]{64}$/.test(e.weight_root_sha)) return { ok: false, at: i, reason: 'hash fields must be 64 lowercase hex chars' };
    const expect = sha256hex(canonEntry(e));
    if (e.sha !== expect) return { ok: false, at: i, reason: 'entry sha mismatch (fields edited after sealing)' };
    prev = e.sha;
  }
  return { ok: true, n: chain.length };
}

export function verify(chain) {
  return verifyWhy(chain).ok;
}

// ── train: per-sample SGD, seeded Fisher–Yates shuffle from the SAME LCG ────────
// One TICK per sample. Epoch receipt carries the mean PRE-STEP loss and the
// weight root AFTER the last tick. Deterministic end to end for a fixed seed.
export function train(netOrGraph, { data, epochs, lr, seed }) {
  const net = netOrGraph.graph ? netOrGraph : loadNet(netOrGraph);
  if (!Array.isArray(data) || data.length === 0) throw new TypeError('train: data must be a non-empty array of {x, y} samples');
  if (!Number.isInteger(epochs) || epochs < 0) throw new TypeError('train: epochs must be a non-negative integer');
  if (!(typeof lr === 'number' && Number.isFinite(lr) && lr > 0)) throw new TypeError('train: lr must be a positive finite number');
  if (!Number.isInteger(seed)) throw new TypeError('train: seed must be an integer');

  const r = lcg(seed);
  const env = initEnv(net, seed, r); // continues the SAME LCG stream as the shuffle
  const chain = [];
  const metrics = [];
  let prev = GENESIS;

  const indices = data.map((_, i) => i);
  for (let epoch = 0; epoch < epochs; epoch++) {
    for (let i = indices.length - 1; i > 0; i--) {
      const j = Math.floor(r.next() * (i + 1));
      [indices[i], indices[j]] = [indices[j], indices[i]];
    }
    let total = 0;
    for (const idx of indices) {
      const s = data[idx];
      evaluateForward(net, env, s);
      total += env[net.lossId]; // pre-step: what this tick's gradient was taken at
      const g = evaluateBackward(net, env);
      for (const gc of net.gradCells) env[gc.id] = g.get(gc.params.of) || 0;
      applyTick(net, env, lr);
    }
    const loss = total / data.length;

    const entry = {
      v: 1,
      seq: epoch + 1,
      epoch,
      loss,
      loss_sha: lossShaOf(loss),
      weight_root_sha: weightRootSha(net, env),
      prev,
    };
    entry.sha = sha256hex(canonEntry(entry));
    chain.push(entry);
    metrics.push({ epoch, loss });
    prev = entry.sha;
  }
  return { metrics, chain, tip: prev, env, finalLoss: chain.length ? chain[chain.length - 1].loss : undefined };
}

export function makeXorData() {
  return [
    { x: [0, 0], y: 0 },
    { x: [0, 1], y: 1 },
    { x: [1, 0], y: 1 },
    { x: [1, 1], y: 0 },
  ];
}

export function makeSineData({ n = 64, seed = 7 } = {}) {
  const r = lcg(seed);
  const out = [];
  for (let i = 0; i < n; i++) {
    const x = -Math.PI + 2 * Math.PI * r.next();
    out.push({ x: [x], y: Math.sin(x) });
  }
  return out;
}

// ── the pin (measured on this checkout; matches quilt-nn @ 1ae7977) ─────────────
export const PIN = {
  seed: 42,
  epochs: 3000,
  lr: 0.5,
  xor_loss_max: 0.05, // the failure condition
};

// Direct run: node recipes/r2-cellgraph-mlp-training/index.mjs
export async function run(ctx = {}) {
  const { seed = PIN.seed, log = () => {} } = ctx;
  const net = loadNet(buildMLP({ sizes: [2, 4, 1], hiddenAct: 'tanh', outAct: 'sigmoid' }));
  log(`r2: XOR 2-4-1 tanh/sigmoid, seed=${seed}, epochs=${PIN.epochs}, lr=${PIN.lr}, per-sample SGD`);
  const t0 = performance.now();
  const { chain, tip, finalLoss } = train(net, { data: makeXorData(), epochs: PIN.epochs, lr: PIN.lr, seed });
  const v = verifyWhy(chain);
  log(`done: loss=${finalLoss.toExponential(3)} chain=${chain.length} verify=${v.ok} tip=${tip.slice(0, 16)}… (${(performance.now() - t0).toFixed(0)}ms)`);
  return { xor_loss_final: finalLoss, chain_len: chain.length, verify_ok: v.ok ? 1 : 0, tip };
}

export async function assertions() {
  const a = await run({});
  const b = await run({});
  const same = JSON.stringify(a) === JSON.stringify(b);
  const seed43 = await run({ seed: 43 });
  const v = verifyWhy(loadNet(buildMLP({ sizes: [2, 4, 1], hiddenAct: 'tanh', outAct: 'sigmoid' })) && []); // chain check below
  void v;
  return [
    {
      assertion: `XOR loss < ${PIN.xor_loss_max} (seed 42, ${PIN.epochs} epochs, lr ${PIN.lr})`,
      actual: a.xor_loss_final.toExponential(3),
      pass: a.xor_loss_final < PIN.xor_loss_max,
    },
    {
      assertion: `epoch receipt chain verifies (${a.chain_len} entries)`,
      actual: a.verify_ok === 1 ? 'valid' : 'INVALID',
      pass: a.verify_ok === 1,
    },
    {
      assertion: 'two runs byte-identical (chain tip equal)',
      actual: same ? `tip ${a.tip.slice(0, 12)}… twice` : 'DIVERGED',
      pass: same,
    },
    {
      assertion: 'seed 43 diverges — the pin is seed-specific, not universal',
      actual: seed43.tip === a.tip ? 'SAME TIP (bad)' : 'different tip',
      pass: seed43.tip !== a.tip,
    },
  ];
}

// The rule's own failure mode, demonstrated live (--negative-control):
// the activation-ceiling trap. Same recipe mechanics, but the target spans
// negatives (sine) while the output cell is a SIGMOID — bounded to [0,1], it
// physically cannot represent sin(x) < 0. The net plateaus at a large loss and
// every hyperparameter in the dark does not help; the receipts record the
// plateau faithfully. This is the honest finding quilt-nn shipped in 67-d
// (sigmoid-out sine plateaued at MSE 0.2366) — reproduced here. The fix is
// architectural, not optimizational: tanh out (unbounded sign) converges.
export async function negativeControlDemo() {
  const sine = makeSineData({ n: 64, seed: 7 });
  const brokenNet = loadNet(buildMLP({ sizes: [1, 16, 1], hiddenAct: 'tanh', outAct: 'sigmoid' }));
  const broken = train(brokenNet, { data: sine, epochs: 3000, lr: 0.1, seed: 42 });
  const fixedNet = loadNet(buildMLP({ sizes: [1, 16, 1], hiddenAct: 'tanh', outAct: 'tanh' }));
  const fixed = train(fixedNet, { data: sine, epochs: 3000, lr: 0.1, seed: 42 });
  return {
    broken: 'sigmoid output on a signed target (sine): the [0,1] ceiling cannot represent sin(x) < 0',
    sigmoid_out_loss: broken.finalLoss,
    tanh_out_loss: fixed.finalLoss,
    failure_condition_fires: broken.finalLoss >= 0.05,
    verdict: 'architectural ceiling, not an optimization problem — the receipted chain proves the plateau was real, not a bug in the log',
  };
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  if (process.argv.includes('--negative-control')) {
    console.log(JSON.stringify(await negativeControlDemo(), null, 2));
  } else {
    const metrics = await run({ log: (m) => console.log('[log]', m) });
    console.log('metrics:', JSON.stringify(metrics, null, 2));
    for (const a of await assertions()) console.log(`${a.pass ? 'PASS' : 'FAIL'}  ${a.assertion}  →  ${a.actual}`);
  }
}

quilt-ml-recipes-main/recipes/r3-receipt:
// r3-receipt-chained-run-ledger — a recipe card, not a library.
//
// RULE: a run does not count as done until it is sealed into an append-only
// ledger whose entries are hash-linked, and the ledger can prove its own
// integrity with zero external dependencies. Entry shape (quilt-lab idiom):
//
//   { name, run_id, metrics_sha, prev_seal, seal }
//
//   metrics_sha  sha256 of the canonical metrics bytes (the evidence)
//   prev_seal    the previous entry's seal (genesis = 64 zeros)
//   seal         sha256 over the canonical JSON of the four payload fields
//
// verify() recomputes every seal and every link; double-sealing the same run is
// refused; evidence is re-hashed whenever the metrics are at hand.
//
// LINEAGE: SuperInstance/quilt-lab @ d2a8b2b (67-b) `seal`/`verify` verbs +
// SuperInstance/quilt-neighbourhood @ 40762c4 (66-a) receipt-chain discipline.
// Honest limit, stated once (same as any hash chain, including git): a bare
// chain cannot detect TRUNCATION OF ITS TAIL without an externally anchored tip.
//
// ZERO dependencies, ESM, Node >= 18.

import { createHash } from 'node:crypto';

export const meta = {
  id: 'r3-receipt-chained-run-ledger',
  title: 'Receipt-chained run ledger (seal/verify)',
  lineage: 'SuperInstance/quilt-lab (67-b) + quilt-neighbourhood (66-a)',
  proves: 'runs seal into a tamper-evident hash chain; tampering is detected, double-seals are refused',
};

export const GENESIS = '0'.repeat(64);

// Canonical JSON: recursive sorted keys — two seals of the same payload must
// hash the same bytes regardless of key insertion order.
export function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value !== null && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value).sort()) out[k] = canonical(value[k]);
    return out;
  }
  return value;
}
export const canonicalJson = (v) => JSON.stringify(canonical(v));
export const sha256Hex = (data) => createHash('sha256').update(data).digest('hex');

// metricsFileBytes: the canonical metrics.json bytes a quilt-lab run writes
// (pretty canonical JSON + trailing newline). Seal THIS, not the object, so the
// ledger commits to the exact bytes a fresh clone can re-derive and re-hash.
export const metricsFileBytes = (metrics) => JSON.stringify(canonical(metrics), null, 2) + '\n';

export class RunLedger {
  constructor() {
    this.entries = [];
  }

  // seal a run: refuses double-seals, refuses malformed payloads. Nothing is
  // appended on refusal — a failed op leaves the chain untouched.
  seal({ name, runId, metrics }) {
    if (!name || typeof name !== 'string') throw new Error('seal: name required');
    if (!runId || typeof runId !== 'string') throw new Error('seal: runId required');
    if (!metrics || typeof metrics !== 'object') throw new Error('seal: metrics object required');
    if (this.entries.some((e) => e.name === name && e.run_id === runId)) {
      throw new Error(`seal refused: run ${name}/${runId} is already sealed (one run seals exactly once)`);
    }
    const metrics_sha = sha256Hex(metricsFileBytes(metrics));
    const prev_seal = this.entries.length ? this.entries[this.entries.length - 1].seal : GENESIS;
    const payload = { metrics_sha, name, prev_seal, run_id: runId };
    const entry = { ...payload, seal: sha256Hex(canonicalJson(payload)) };
    this.entries.push(entry);
    return entry.seal;
  }

  // verify the whole chain: JSON shape, hex fields, linkage, seal recomputation.
  // Returns {ok, tip, reason, at} — reason/at name the first breach, if any.
  verify() {
    let prev = GENESIS;
    for (let i = 0; i < this.entries.length; i++) {
      const e = this.entries[i];
      if (typeof e !== 'object' || e === null || Array.isArray(e)) {
        return { ok: false, at: i, reason: 'entry is not an object' };
      }
      for (const f of ['name', 'run_id', 'metrics_sha', 'prev_seal', 'seal']) {
        if (typeof e[f] !== 'string' || !e[f]) return { ok: false, at: i, reason: `field ${f} missing or not a string` };
      }
      if (!/^[0-9a-f]{64}$/.test(e.metrics_sha) || !/^[0-9a-f]{64}$/.test(e.seal)) {
        return { ok: false, at: i, reason: 'hash fields must be 64 lowercase hex chars' };
      }
      if (e.prev_seal !== prev) return { ok: false, at: i, reason: `prev_seal linkage broken (expected ${prev.slice(0, 12)}…)` };
      const expect = sha256Hex(canonicalJson({ metrics_sha: e.metrics_sha, name: e.name, prev_seal: e.prev_seal, run_id: e.run_id }));
      if (e.seal !== expect) return { ok: false, at: i, reason: 'seal mismatch — entry edited after sealing' };
      prev = e.seal;
    }
    return { ok: true, tip: prev, n: this.entries.length };
  }

  // evidence re-hash: given the metrics a seal committed to, check the bytes.
  verifyEvidence(entry, metrics) {
    return sha256Hex(metricsFileBytes(metrics)) === entry.metrics_sha;
  }

  alreadySealed(name, runId) {
    return this.entries.some((e) => e.name === name && e.run_id === runId);
  }
}

// ── the demo experiment: two tiny deterministic runs worth sealing ──────────────
// (The ledger is experiment-agnostic; R1-style metrics keep the example real.)
function demoMetrics(seed) {
  let a = seed >>> 0;
  const rand = () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  let se = 0;
  for (let i = 0; i < 50; i++) { const x = rand() * 2 - 1; const e = 2 * x + 1 - (2 * x + 1 + (rand() * 2 - 1) * 0.1); se += e * e; }
  return { mse_final: Math.round((se / 50) * 1e12) / 1e12, n: 50 };
}

export async function run(ctx = {}) {
  const { log = () => {} } = ctx;
  const ledger = new RunLedger();
  const metricsA = demoMetrics(7);
  const metricsB = demoMetrics(11);
  log(`run-a metrics: ${JSON.stringify(metricsA)}`);
  log(`run-b metrics: ${JSON.stringify(metricsB)}`);
  const s1 = ledger.seal({ name: 'linear-fit', runId: '20261001T000000Z-aaa111', metrics: metricsA });
  const s2 = ledger.seal({ name: 'linear-fit', runId: '20261001T000000Z-bbb222', metrics: metricsB });
  log(`sealed run-a → ${s1.slice(0, 16)}…`);
  log(`sealed run-b → ${s2.slice(0, 16)}…`);
  const v = ledger.verify();
  log(`verify: ${JSON.stringify(v)}`);

  // double-seal refusal + tamper detection as part of the run's own report
  let double_refused = false;
  try { ledger.seal({ name: 'linear-fit', runId: '20261001T000000Z-aaa111', metrics: metricsA }); } catch { double_refused = true; }
  const tampered = new RunLedger();
  tampered.seal({ name: 'linear-fit', runId: '20261001T000000Z-aaa111', metrics: metricsA });
  tampered.seal({ name: 'linear-fit', runId: '20261001T000000Z-bbb222', metrics: metricsB });
  tampered.entries[0].metrics_sha = '0'.repeat(64);
  const tamper_detected = !tampered.verify().ok;

  return {
    verify_ok: v.ok ? 1 : 0,
    entries: ledger.entries.length,
    tip: v.tip,
    double_refused: double_refused ? 1 : 0,
    tamper_detected: tamper_detected ? 1 : 0,
  };
}

export async function assertions() {
  const m = await run({});
  return [
    {
      assertion: 'chain verifies after 2 seals (linkage + seal recomputation)',
      actual: m.verify_ok === 1 ? `valid, tip ${m.tip.slice(0, 12)}…` : 'INVALID',
      pass: m.verify_ok === 1,
    },
    {
      assertion: 'double-seal of the same run refused',
      actual: m.double_refused === 1 ? 'refused' : 'ACCEPTED (bad)',
      pass: m.double_refused === 1,
    },
    {
      assertion: 'flipped metrics_sha in a sealed entry breaks verify()',
      actual: m.tamper_detected === 1 ? 'detected' : 'MISSED (bad)',
      pass: m.tamper_detected === 1,
    },
    {
      assertion: 'evidence re-hash: sealed metrics bytes match the seal',
      actual: 'match',
      pass: (() => {
        const l = new RunLedger();
        const metrics = demoMetrics(7);
        const e = l.entries.length;
        void e;
        l.seal({ name: 'linear-fit', runId: 'x', metrics });
        return l.verifyEvidence(l.entries[0], metrics);
      })(),
    },
  ];
}

// The rule's own failure mode, demonstrated live (--negative-control):
// TAIL TRUNCATION. Drop the last N entries of a valid chain and verify() still
// says ok — a bare hash chain proves the prefix, not the completeness. That is
// why the doctrine says: verify the chain, then ANCHOR THE TIP somewhere the
// operator can see (a commit message, a release body, a human's notebook).
export async function negativeControlDemo() {
  const ledger = new RunLedger();
  ledger.seal({ name: 'linear-fit', runId: 'r1', metrics: demoMetrics(7) });
  ledger.seal({ name: 'linear-fit', runId: 'r2', metrics: demoMetrics(11) });
  ledger.seal({ name: 'linear-fit', runId: 'r3', metrics: demoMetrics(13) });
  const full = ledger.verify();
  ledger.entries.pop(); // the operator never hears about r3
  const truncated = ledger.verify();
  return {
    broken: 'tail truncation — the last seal is silently dropped',
    full_tip: full.tip,
    entries_before: 3,
    entries_after: ledger.entries.length,
    truncated_verify_ok: truncated.ok,
    anchored_tip: full.tip,
    verdict: 'bare chain verified the truncated log — anchor the tip externally (tag, release, commit) to close this hole',
  };
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  if (process.argv.includes('--negative-control')) {
    console.log(JSON.stringify(await negativeControlDemo(), null, 2));
  } else {
    const metrics = await run({ log: (m) => console.log('[log]', m) });
    console.log('metrics:', JSON.stringify(metrics, null, 2));
    for (const a of await assertions()) console.log(`${a.pass ? 'PASS' : 'FAIL'}  ${a.assertion}  →  ${a.actual}`);
  }
}

quilt-ml-recipes-main/recipes/r4-judge-c:
// r4-judge-calibration-battery — a recipe card, not a library.
//
// RULE: a judge (an LLM asked for probabilities) is only trustworthy if a
// known-answer battery scores it — Brier + MSE against exactly-known truths —
// AND the score survives a negative control: shuffle the predictions across
// questions; if the score does not get strictly worse, the predictions carry no
// question-specific information and the scoring is vacuous. Constant predictors
// must FAIL this gate. Calibration without a shuffle control is decoration.
//
// THIS CARD RUNS OFFLINE: the judge is a deterministic MOCK (seeded, quantized,
// mildly over-predicting small probabilities — the shape the live jev-1.13.0
// battery showed), so the scoring + control machinery is testable with zero API
// calls. The live battery and its numbers live in typesafe-quilts; the mock is
// labeled MOCK everywhere and never pretends to be a model.
//
// LINEAGE: SuperInstance/typesafe-quilts @ 93b0830 (67-c) — lib/brier.mjs +
// experiments/calibration (live: Brier 0.1133, perfect-predictor floor 0.0996,
// NC-CAL truth-shuffle 11.5× worse, p = 0/2000). See its JUDGE-PROTOCOL.md for
// the wire shapes and budget doctrine before swapping in a real client.
//
// ZERO dependencies, ESM, Node >= 18.

export const meta = {
  id: 'r4-judge-calibration-battery',
  title: 'Judge calibration battery (Brier + shuffle NC, offline mock)',
  lineage: 'SuperInstance/typesafe-quilts (67-c) — lib/brier.mjs + calibration battery',
  proves: 'judge scores are gated by a shuffle negative control; constant predictors are refused',
};

// ── seeded PRNG + shuffle (mulberry32, same family as the lineage repos) ────────
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export function shuffled(arr, rand) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ── scoring ──────────────────────────────────────────────────────────────────────
export function brier(predictions, outcomes) {
  if (predictions.length !== outcomes.length || predictions.length === 0) {
    throw new Error('brier: predictions/outcomes must be same non-zero length');
  }
  let sum = 0;
  for (let i = 0; i < predictions.length; i++) {
    const p = checkProb(predictions[i]);
    const o = outcomes[i];
    if (o !== 0 && o !== 1) throw new Error('brier: outcomes must be 0 or 1');
    sum += (p - o) * (p - o);
  }
  return sum / predictions.length;
}

export function mseAgainstTruth(predictions, truths) {
  if (predictions.length !== truths.length || predictions.length === 0) {
    throw new Error('mseAgainstTruth: length mismatch');
  }
  let sum = 0;
  for (let i = 0; i < predictions.length; i++) {
    sum += (checkProb(predictions[i]) - checkProb(truths[i])) ** 2;
  }
  return sum / predictions.length;
}

function checkProb(p) {
  if (typeof p !== 'number' || Number.isNaN(p) || p < 0 || p > 1) {
    throw new Error(`probability out of [0,1]: ${p}`);
  }
  return p;
}

// ── the known-answer battery: events with EXACTLY computable probabilities ──────
// Mid/high truths only (small-truth single-draw outcomes make the outcome Brier
// degenerate — the fixture lesson from 67-c). Traps included where the naive
// answer is wrong: two-boys (1/3, not 1/2), birthday (just over 1/2).
export const BATTERY = [
  { name: 'coin_heads', truth: 0.5 },
  { name: 'die_even', truth: 0.5 },
  { name: 'dice_sum7_or_11', truth: 8 / 36 }, // 6/36 + 2/36
  { name: 'card_face', truth: 12 / 52 },
  { name: 'coin2_atleastone_h', truth: 0.75 },
  { name: 'children_two_boys', truth: 1 / 3 }, // trap: naive says 1/2
  { name: 'birthday23_shared', truth: 0.5073 }, // trap: naive says "unlikely"
  { name: 'facecard_given_face', truth: 1 / 3 }, // trap: conditional
];
export const TRUTHS = BATTERY.map((q) => q.truth);

// Frozen BEFORE any (mock) predictions: the outcome vector is seeded
// Bernoulli(truth) draws. Deterministic, committed here, never tuned.
export const OUTCOME_SEED = 0x5eedb003;
export const OUTCOMES = (() => {
  const rng = mulberry32(OUTCOME_SEED);
  return BATTERY.map((q) => (rng() < q.truth ? 1 : 0));
})();

// ── the MOCK judge (offline stand-in for a real System One client) ──────────────
// Deterministic per-question jitter, quantized to 0.01 (real judges quantize),
// biased upward on small truths (the over-prediction the live battery measured).
export function mockJudge(truths, seed = 0x10b) {
  const rng = mulberry32(seed);
  return truths.map((t) => {
    const jitter = Math.floor(rng() * 9) * 0.01 - 0.02; // −0.02 … +0.06, step 0.01
    return Math.min(1, Math.max(0, Math.round((t + jitter) * 100) / 100));
  });
}

// ── the negative control (NC-CAL): the shuffle gate ─────────────────────────────
// PRIMARY, deterministic: shuffle predictions across questions against the
// exactly-known truths; the shuffled MSE-vs-truth must be STRICTLY worse, or the
// predictions carry no question-specific information.
export const NC_SHUFFLE_SEED = 0xca1b57e5; // fixed before any scoring, like the lineage repo

export function negativeControl(predictions, { truths = TRUTHS, outcomes = OUTCOMES, shuffleSeed = NC_SHUFFLE_SEED } = {}) {
  const unshuffledMse = mseAgainstTruth(predictions, truths);
  const canonicalMse = mseAgainstTruth(shuffled(predictions, mulberry32(shuffleSeed)), truths);
  const result = {
    metric: 'mse_against_known_truth (primary, deterministic)',
    unshuffled_mse: unshuffledMse,
    canonical_shuffle_mse: canonicalMse,
    strictly_worse: canonicalMse > unshuffledMse,
  };
  if (outcomes) {
    result.outcome_brier = brier(predictions, outcomes); // reported, not gated
  }
  result.pass = result.strictly_worse;
  return result;
}

export const PIN = {
  mse_vs_truth_max: 0.01, // the mock stays within jitter distance of truth
  outcome_brier_max: 0.35, // frozen fixture → fully deterministic value
};

export async function run(ctx = {}) {
  const { log = () => {} } = ctx;
  log('r4-judge-calibration-battery: MOCK judge (offline, deterministic), 8 known-answer questions');
  log(`fixture outcomes (seed 0x${OUTCOME_SEED.toString(16)}): [${OUTCOMES.join(',')}]`);

  const preds = mockJudge(TRUTHS);
  log(`mock predictions: [${preds.join(', ')}]`);

  const mse = mseAgainstTruth(preds, TRUTHS);
  const obrier = brier(preds, OUTCOMES);
  const nc = negativeControl(preds);
  log(`mse_vs_truth=${mse.toExponential(3)} outcome_brier=${obrier.toFixed(4)}`);
  log(`NC-CAL: unshuffled=${nc.unshuffled_mse.toExponential(3)} shuffled=${nc.canonical_shuffle_mse.toExponential(3)} pass=${nc.pass}`);

  const perfect = mseAgainstTruth(TRUTHS, TRUTHS);
  const constant = negativeControl(TRUTHS.map(() => 0.5));
  const perfectBrier = brier(TRUTHS, OUTCOMES); // prediction = truth: the outcome floor
  log(`perfect predictor: mse=${perfect}, outcome_brier=${perfectBrier.toFixed(4)} (floor)`);
  log(`constant-0.5 control: gate pass=${constant.pass} (must be refused)`);

  return {
    mock: 1,
    n_questions: BATTERY.length,
    mse_vs_truth: mse,
    outcome_brier: obrier,
    perfect_outcome_brier: perfectBrier,
    nc_pass: nc.pass ? 1 : 0,
    nc_unshuffled_mse: nc.unshuffled_mse,
    nc_shuffle_mse: nc.canonical_shuffle_mse,
    constant_refused: constant.pass ? 0 : 1,
  };
}

export async function assertions() {
  const m = await run({});
  return [
    {
      assertion: `mock judge mse-vs-truth ≤ ${PIN.mse_vs_truth_max}`,
      actual: m.mse_vs_truth.toExponential(3),
      pass: m.mse_vs_truth <= PIN.mse_vs_truth_max,
    },
    {
      assertion: `outcome Brier ≤ ${PIN.outcome_brier_max} (frozen fixture)`,
      actual: m.outcome_brier.toFixed(4),
      pass: m.outcome_brier <= PIN.outcome_brier_max,
    },
    {
      assertion: 'NC-CAL: truth-shuffle strictly worse than unshuffled',
      actual: `shuffle ${m.nc_shuffle_mse.toFixed(4)} > ${m.nc_unshuffled_mse.toFixed(4)}`,
      pass: m.nc_pass === 1,
    },
    {
      assertion: 'vacuity control: constant-0.5 predictor FAILS the shuffle gate',
      actual: m.constant_refused === 1 ? 'refused' : 'PASSED (bad)',
      pass: m.constant_refused === 1,
    },
  ];
}

// The rule's own failure mode, demonstrated live (--negative-control):
// a CONFIDENTLY WRONG judge that still looks good on raw Brier. Against a
// lopsided outcome vector, "always say never" scores a fine Brier while knowing
// nothing — the exact vacuity the shuffle gate exists to catch. Shown: a
// constant 0.05 predictor on this fixture gets a respectable outcome Brier but
// is refused by the gate (shuffle changes nothing ⇒ not strictly worse).
export async function negativeControlDemo() {
  const neverPredictor = TRUTHS.map(() => 0.05);
  const obrier = brier(neverPredictor, OUTCOMES);
  const nc = negativeControl(neverPredictor);
  const ones = OUTCOMES.reduce((a, b) => a + b, 0);
  return {
    broken: 'constant-0.05 predictor: raw outcome Brier looks acceptable, knowledge is zero',
    outcome_ones: `${ones}/${OUTCOMES.length}`,
    outcome_brier: obrier,
    brier_of_all_never_beats_random_guessing: obrier < 0.25,
    nc_gate_pass: nc.pass,
    nc_unshuffled_mse: nc.unshuffled_mse,
    nc_shuffle_mse: nc.canonical_shuffle_mse,
    verdict: 'raw Brier alone would certify ignorance — the shuffle gate refuses it',
  };
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  if (process.argv.includes('--negative-control')) {
    console.log(JSON.stringify(await negativeControlDemo(), null, 2));
  } else {
    const metrics = await run({ log: (m) => console.log('[log]', m) });
    console.log('metrics:', JSON.stringify(metrics, null, 2));
    for (const a of await assertions()) console.log(`${a.pass ? 'PASS' : 'FAIL'}  ${a.assertion}  →  ${a.actual}`);
  }
}

quilt-ml-recipes-main/recipes/r6-sheet-c:
// r6-sheet-convergence-diff-dag — a recipe card, not a library.
//
// RULE: two replicas of a quilt sheet that diverge in a partition and then
// exchange every diff they know converge to ONE revision and ONE state — no
// matter who merges into whom first. The mechanism, in three moves:
//
//   1. IDENTITY IS CONTENT. A diff is {sheet, cell, op, value, prev, author,
//      tick, parents}; id = sha256(canonical(diff-without-id)). Tamper with any
//      field and every replica rejects the diff on sight.
//   2. THE LOG IS A DAG, NOT A LINE. parents = the diff ids the author had seen;
//      divergence makes siblings, a merge is just shipping missing diffs.
//   3. THE FOLD IS A PURE FUNCTION OF THE DAG. Topological order, ties broken by
//      id, registered merge policy (P1–P4). Same diff set ⇒ same state bytes —
//      arrival order is irrelevant.
//
// Determinism note: this card uses a LOGICAL clock (tick = 1 + max(parent
// ticks)) instead of the lineage repo's Date.now(), so diff ids — and therefore
// the revision hash — are reproducible across runs, not just within one.
//
// LINEAGE: SuperInstance/quilt-neighbourhood @ 40762c4 (66-a) — src/replica.mjs
// + src/diff.mjs, mini version of its T1 (3-replica, 10 seeded merge orders);
// here: 2 replicas, the smallest experiment that still proves convergence.
//
// ZERO dependencies, ESM, Node >= 18.

import { createHash } from 'node:crypto';

export const meta = {
  id: 'r6-sheet-convergence-diff-dag',
  title: 'Sheet convergence on a diff-DAG (2-replica mini-T1)',
  lineage: 'SuperInstance/quilt-neighbourhood (66-a) — src/replica.mjs, src/diff.mjs',
  proves: 'divergent replicas converge to one revision; forged diffs are rejected on sight',
};

export const GENESIS = 'GENESIS';
export const OP = { SET: 'set', REMOVE: 'remove' };
const TOMBSTONE = '__tombstone__';

// canonical JSON (sorted keys, recursive) — the bytes a diff id commits to
export function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value !== null && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value).sort()) out[k] = canonical(value[k]);
    return out;
  }
  return value;
}
export const canonicalJson = (v) => JSON.stringify(canonical(v));
export const sha256 = (s) => createHash('sha256').update(s, 'utf8').digest('hex');
export const canonicalSha = (v) => sha256(canonicalJson(v));

export function makeDiff({ sheet = 'default', cell, op, value, prev = null, author, tick = 0, parents }) {
  if (!cell) throw new Error('diff requires cell');
  if (op !== OP.SET && op !== OP.REMOVE) throw new Error(`unknown op ${op}`);
  if (op === OP.REMOVE && value !== undefined) throw new Error('remove carries no value');
  if (!parents || parents.length === 0) throw new Error('diff requires >=1 parent');
  const d = { sheet, cell, op, value: value === undefined ? null : value, prev, author, tick, parents: [...parents] };
  d.id = canonicalSha(d);
  return d;
}

export function verifyDiff(d) {
  const { id, ...rest } = d;
  if (!id) return { ok: false, reason: 'no id' };
  const expect = canonicalSha(rest);
  if (expect !== id) return { ok: false, reason: `id mismatch: got ${id.slice(0, 12)} want ${expect.slice(0, 12)}` };
  return { ok: true };
}

export class Replica {
  constructor(name, sheet = 'default') {
    this.name = name;
    this.sheet = sheet;
    this.diffs = new Map(); // id -> diff
    this.heads = new Set(); // diff ids with no known children
    this._anc = new Map(); // id -> Set(ancestor ids), memoized
  }

  ancestors(id) {
    if (this._anc.has(id)) return this._anc.get(id);
    if (id === GENESIS) { const s = new Set(); this._anc.set(id, s); return s; }
    const d = this.diffs.get(id);
    const s = new Set();
    if (d) for (const p of d.parents) {
      s.add(p);
      for (const a of this.ancestors(p)) s.add(a);
    }
    this._anc.set(id, s);
    return s;
  }

  // local write: parents = current heads, logical tick = 1 + max(parent ticks)
  set(cell, value, author = this.name) {
    const parents = this._headIds();
    const tick = 1 + Math.max(0, ...parents.map((p) => (p === GENESIS ? 0 : this.diffs.get(p).tick)));
    const d = makeDiff({ sheet: this.sheet, cell, op: OP.SET, value, prev: this.valueAt(cell), author, tick, parents });
    this._absorb(d);
    return d;
  }

  remove(cell, author = this.name) {
    const parents = this._headIds();
    const tick = 1 + Math.max(0, ...parents.map((p) => (p === GENESIS ? 0 : this.diffs.get(p).tick)));
    const d = makeDiff({ sheet: this.sheet, cell, op: OP.REMOVE, value: undefined, prev: this.valueAt(cell), author, tick, parents });
    this._absorb(d);
    return d;
  }

  // remote receive: known = idempotent no-op; tampered = rejected (never enters the DAG)
  receive(d) {
    if (this.diffs.has(d.id)) return { accepted: false, reason: 'known' };
    const v = verifyDiff(d);
    if (!v.ok) return { accepted: false, reason: v.reason };
    this._absorb(d);
    return { accepted: true, reason: 'ok' };
  }

  _absorb(d) {
    this.diffs.set(d.id, d);
    for (const p of d.parents) if (p !== GENESIS) this.heads.delete(p);
    this.heads.add(d.id);
  }

  _headIds() {
    return this.heads.size ? [...this.heads].sort() : [GENESIS];
  }

  // deterministic fold: topo order (sorted ids, queue re-sorted every pop), P1–P4
  _topo() {
    const ids = [...this.diffs.keys()].sort();
    const indeg = new Map();
    const children = new Map();
    for (const id of ids) { indeg.set(id, 0); children.set(id, []); }
    for (const id of ids) for (const p of this.diffs.get(id).parents) {
      if (p !== GENESIS && this.diffs.has(p)) { indeg.set(id, indeg.get(id) + 1); children.get(p).push(id); }
    }
    const queue = ids.filter((id) => indeg.get(id) === 0);
    const out = [];
    while (queue.length) {
      queue.sort();
      const id = queue.shift();
      out.push(id);
      for (const c of children.get(id)) {
        indeg.set(c, indeg.get(c) - 1);
        if (indeg.get(c) === 0) queue.push(c);
      }
    }
    if (out.length !== ids.length) throw new Error('diff DAG has a cycle — identity is broken');
    return out;
  }

  // the fold, with the registered merge policy:
  //   P1 set vs tombstone, causally after → resurrect
  //   P2 set vs tombstone, concurrent / value vs concurrent remove → REMOVE WINS
  //   P3 set vs set, concurrent → lexicographically smaller diff id wins
  //   P4 remove vs remove, any relation → tombstone (idempotent)
  state() {
    const cellState = new Map();
    for (const id of this._topo()) {
      const d = this.diffs.get(id);
      const cur = cellState.get(d.cell);
      if (d.op === OP.SET) {
        if (!cur) { cellState.set(d.cell, { kind: 'value', by: id, value: d.value }); continue; }
        if (cur.kind === TOMBSTONE) {
          if (this.ancestors(id).has(cur.by)) cellState.set(d.cell, { kind: 'value', by: id, value: d.value }); // P1
          continue; // else P2: remove wins
        }
        if (this.ancestors(id).has(cur.by)) { cellState.set(d.cell, { kind: 'value', by: id, value: d.value }); continue; }
        if (this.ancestors(cur.by).has(id)) continue; // superseded
        if (id < cur.by) cellState.set(d.cell, { kind: 'value', by: id, value: d.value }); // P3
      } else {
        if (!cur) { cellState.set(d.cell, { kind: TOMBSTONE, by: id }); continue; }
        if (cur.kind === TOMBSTONE) continue; // P4
        cellState.set(d.cell, { kind: TOMBSTONE, by: id }); // P2 remove wins (causal or concurrent)
      }
    }
    const out = {};
    for (const [cell, s] of cellState) if (s.kind === 'value') out[cell] = s.value;
    return out;
  }

  valueAt(cell) {
    const s = this.state()[cell];
    return s === undefined ? null : s;
  }

  // revision = pure function of the head set — identical DAGs, identical bytes
  revision() {
    return sha256([...this.heads].sort().join(','));
  }

  diffCount() { return this.diffs.size; }
}

// merge(src -> dst): ship dst every diff src knows and dst lacks.
export function merge(src, dst) {
  const missing = src._topo().filter((id) => !dst.diffs.has(id));
  let applied = 0;
  for (const id of missing) applied += dst.receive(src.diffs.get(id)).accepted ? 1 : 0;
  return { applied, revision: dst.revision() };
}

export const stateBytes = (r) => canonicalJson(r.state());

// ── the recipe run: 2-replica mini-T1 ───────────────────────────────────────────
export async function run(ctx = {}) {
  const { log = () => {} } = ctx;
  // partition: both replicas start from the same base, then diverge
  const base = new Replica('base');
  base.set('lr', 0.5, 'base');
  const a = new Replica('alpha'); const b = new Replica('beta');
  merge(base, a); merge(base, b);

  // divergent work in isolation
  const da = a.set('loss', 0.31);
  const db = b.set('loss', 0.27); // CONCURRENT with da: P3 decides
  b.set('note', 'from-beta'); // only b knows this
  log(`partition: alpha sets loss=0.31 (${da.id.slice(0, 12)}…), beta sets loss=0.27 (${db.id.slice(0, 12)}…) + note`);

  // rejoin, both orders
  merge(a, b); merge(b, a);
  const revA = a.revision(); const revB = b.revision();
  const winner = da.id < db.id ? 0.31 : 0.27; // P3: smaller diff id wins
  log(`rejoined: revisions equal=${revA === revB}, loss=${a.state().loss} (P3 winner: smaller id → ${winner})`);

  // forged diff rejected on sight: alpha writes a diff beta has never seen, then
  // the value is flipped in flight with the id left stale — the id check must catch it
  const secret = a.set('payload', 'honest');
  const forged = { ...secret, value: 'tampered' };
  const res = b.receive(forged);
  log(`forged diff → accepted=${res.accepted} reason=${res.reason}`);
  const honestReceipt = b.receive(secret);
  log(`honest diff → accepted=${honestReceipt.accepted}`);

  // determinism: run the whole scenario again — same revision bytes
  const replay = await scenario();
  return {
    revisions_equal: revA === revB ? 1 : 0,
    states_equal: stateBytes(a) === stateBytes(b) ? 1 : 0,
    revision: revA,
    p3_winner_value: a.state().loss,
    p3_expected_value: winner,
    diff_count: a.diffCount(),
    forged_rejected: res.accepted === false && /id mismatch/.test(res.reason) ? 1 : 0,
    honest_diff_accepted: honestReceipt.accepted === true ? 1 : 0,
    replay_revision_equal: replay.revision === revA ? 1 : 0,
  };
}

// the scenario, factored for replay-determinism checking
async function scenario() {
  const base = new Replica('base');
  base.set('lr', 0.5, 'base');
  const a = new Replica('alpha'); const b = new Replica('beta');
  merge(base, a); merge(base, b);
  const da = a.set('loss', 0.31);
  const db = b.set('loss', 0.27);
  b.set('note', 'from-beta');
  merge(a, b); merge(b, a);
  void da; void db;
  return { revision: a.revision() };
}

export async function assertions() {
  const m = await run({});
  return [
    {
      assertion: '2 replicas converge after partition + both-order merge: same revision',
      actual: m.revisions_equal === 1 ? `revision ${m.revision.slice(0, 12)}…` : 'DIVERGED',
      pass: m.revisions_equal === 1,
    },
    {
      assertion: 'folded state bytes identical on both replicas',
      actual: m.states_equal === 1 ? `loss=${m.p3_winner_value} + note, byte-equal` : 'DIVERGED',
      pass: m.states_equal === 1,
    },
    {
      assertion: 'P3 concurrent set-vs-set: smaller diff id wins (deterministic)',
      actual: `loss=${m.p3_winner_value} (expected winner ${m.p3_expected_value})`,
      pass: m.p3_winner_value === m.p3_expected_value,
    },
    {
      assertion: 'forged diff rejected on sight; honest diff accepted',
      actual: m.forged_rejected === 1 && m.honest_diff_accepted === 1 ? 'id mismatch → honest copy accepted' : 'BROKEN',
      pass: m.forged_rejected === 1 && m.honest_diff_accepted === 1,
    },
    {
      assertion: 'scenario replay produces the same revision bytes (logical clock)',
      actual: m.replay_revision_equal === 1 ? 'same revision' : 'DIVERGED',
      pass: m.replay_revision_equal === 1,
    },
  ];
}

// The rule's own failure mode, demonstrated live (--negative-control):
// FOLDING BY ARRIVAL ORDER instead of topo+P3. Two replicas receive the same two
// concurrent sets in opposite orders; an arrival-order fold gives them DIFFERENT
// states — the exact bug the deterministic fold exists to prevent. Convergence
// is not "the messages all arrived"; it is "the same pure function ran".
export async function negativeControlDemo() {
  const base = new Replica('base');
  const a = new Replica('a'); const b = new Replica('b');
  merge(base, a); merge(base, b);
  const d1 = a.set('loss', 0.31);
  const d2 = b.set('loss', 0.27);

  // honest fold: topo + P3 → both replicas agree
  merge(a, b); merge(b, a);
  const honest = stateBytes(a) === stateBytes(b);

  // broken fold: apply whatever arrives last (arrival-order semantics)
  const foldByArrival = (x, y, z) => ({ loss: z.cell === 'loss' ? z.value : (y.cell === 'loss' ? y.value : x.value) });
  const x1 = foldByArrival(null, d1, d2).loss; // x received d1 then d2
  const x2 = foldByArrival(null, d2, d1).loss; // y received d2 then d1
  return {
    broken: 'fold by arrival order instead of topological order + P3',
    honest_fold_states_equal: honest,
    arrival_fold_x_loss: x1,
    arrival_fold_y_loss: x2,
    arrival_fold_diverges: x1 !== x2,
    verdict: 'arrival-order folding leaves the same diff set in two different states — the deterministic fold is the convergence guarantee',
  };
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  if (process.argv.includes('--negative-control')) {
    console.log(JSON.stringify(await negativeControlDemo(), null, 2));
  } else {
    const metrics = await run({ log: (m) => console.log('[log]', m) });
    console.log('metrics:', JSON.stringify(metrics, null, 2));
    for (const a of await assertions()) console.log(`${a.pass ? 'PASS' : 'FAIL'}  ${a.assertion}  →  ${a.actual}`);
  }
}
